Lemma uint32Range_spec pl size min max :
  all_bytes pl -> 0 <= size -> 0 <= min <= max -> max < 2^32 ->
  let '(r, size') := uint32Range pl size min max in
  min <= r <= max /\ 0 <= size' <= size /\ (min = max -> size' = size).
