Lemma int32Range_spec pl size min max :
  all_bytes pl -> 0 <= size -> -2^31 <= min <= max -> max < 2^31 ->
  let '(r, size') := int32Range pl size min max in
  min <= r <= max /\ 0 <= size' <= size.
Proof.
