Lemma uint32Range_range pl size min max :
  0 <= size -> 0 <= min <= max -> max < 2^32 -> max - min < 2^32 - 1 ->
  let '(r, size') := uint32Range pl size min max in
  min <= r <= max /\ 0 <= size' <= size.
