Lemma int32Range_range pl size min max :
  0 <= size -> -2^31 <= min <= max -> max < 2^31 -> max - min < 2^32 - 1 ->
  let '(r, size') := int32Range pl size min max in
  min <= r <= max /\ 0 <= size' <= size.
Proof.
